    public sealed partial class FeatureTableView : UserControl
    {
        public FeatureTableView()
        {
            this.InitializeComponent();
            WeakReferenceMessenger.Default.Register<ShowFeatureTable>(this, (r, m) => OnShowFeatureTable(m.Table, m.FeatureQuery));
        }

        private async void OnShowFeatureTable(FeatureTable table, FeatureQueryResult featureQuery)
        {
            this.Visibility = Visibility.Visible;
            if (featureQuery != null)
                FeatureQuery = featureQuery;
            else
            {
                if(table is ServiceFeatureTable stable)
                    FeatureQuery = await stable.QueryFeaturesAsync(new QueryParameters() { WhereClause = "1=1", ReturnGeometry = false }, QueryFeatureFields.LoadAll);
                else
                    FeatureQuery = await table.QueryFeaturesAsync(new QueryParameters() {  WhereClause = "1=1", ReturnGeometry = false });
            }
        }

