            {
                colorStopsInternal = ColorStops.ToArray();
            }
            [OnDeserialized]
            public void Serialized(StreamingContext context)
            {
                ColorStops = new ObservableCollection<ColorStop>(colorStopsInternal ?? new ColorStop[] { });
            }
        }

