namespace ArcGIS.Samples.ConfigureBasemapStyleParameters
{
    [ArcGIS.Samples.Shared.Attributes.Sample(
        name: "Configure basemap style parameters",
        category: "Map",
        description: "Apply basemap style parameters customization for a basemap, such as displaying all labels in a specific language or displaying every label in their corresponding local language.",
        instructions: "This sample showcases the workflow of configuring basemap style parameters by displaying a basemap with labels in different languages and launches with a `Viewpoint` near Athens, Greece. By default, the `BasemapStyleLanguageStrategy` is set to `Local`, which displays all labels in their corresponding local language. This can be changed to `Global`, which displays all labels in English. The `SpecificLanguage` setting sets all labels to a selected language and overrides the `BasemapStyleLanguageStrategy` settings.",
        tags: new[] { "basemap style", "language", "language strategy", "map", "point", "viewpoint" })]
    [ArcGIS.Samples.Shared.Attributes.OfflineData()]
    public partial class ConfigureBasemapStyleParameters
    {
        /// <summary>
        /// Get the selected language from the language picker.
        /// </summary>
        private string SelectedLanguage
        {
            get => LanguagePicker.SelectedItem as string;
        }

        public ConfigureBasemapStyleParameters()
        {
            InitializeComponent();
            Initialize();
        }

        private void Initialize()
        {
            MyMapView.Map = new Map();
            LanguagePicker.SelectedItem = "None";
            SetNewBasemap();

            // Focus the viewpoint on an area around Athens, Greece to showcase use of the local alphabet when
            // using BasemapStyleLanguageStrategy.Local. The scale is set to the Metropolitan Area level.
            MyMapView.SetViewpoint(new Viewpoint(new MapPoint(2641333, 4577137, SpatialReferences.WebMercator), 288895.277144));

            // Ensure parameter changes are reflected on the basemap.
            GlobalRadioButton.CheckedChanged += StrategyRadioButton_Checked;
            LanguagePicker.SelectedIndexChanged += LanguagePicker_SelectionChanged;
        }

        private void SetNewBasemap()
        {
            BasemapStyleParameters basemapStyleParameters = new BasemapStyleParameters();

            basemapStyleParameters.LanguageStrategy = (bool)GlobalRadioButton.IsChecked ? BasemapStyleLanguageStrategy.Global : BasemapStyleLanguageStrategy.Local;

            switch (SelectedLanguage)
            {
                // A SpecificLanguage setting overrides the BasemapStyleLanguageStrategy settings when
                // the BasemapStyleParameters.SpecificLanguage is a non-empty string.
                // Setting the specific language back to an empty string allows the strategy to be used.
                case "None":
                    basemapStyleParameters.SpecificLanguage = new CultureInfo("");
                    break;

                case "Bulgarian":
                    basemapStyleParameters.SpecificLanguage = new CultureInfo("bg");
                    break;

                case "Greek":
                    basemapStyleParameters.SpecificLanguage = new CultureInfo("el");
                    break;

                case "Turkish":
                    basemapStyleParameters.SpecificLanguage = new CultureInfo("tr");
                    break;
            }

            MyMapView.Map.Basemap = new Basemap(BasemapStyle.ArcGISLightGray, basemapStyleParameters);
        }

        private void LanguagePicker_SelectionChanged(object sender, EventArgs e)
        {
            GlobalRadioButton.IsEnabled = LocalRadioButton.IsEnabled = SelectedLanguage == "None";
            SetNewBasemap();
        }

        private void StrategyRadioButton_Checked(object sender, CheckedChangedEventArgs e)
        {
            SetNewBasemap();
        }
    }
}

namespace ArcGIS.Samples.AuthorMap
{
    public partial class SaveMapPage : ContentPage
    {
        // Raise an event so the listener can access input values when the form has been completed
        public event EventHandler<SaveMapEventArgs> OnSaveClicked;

        public SaveMapPage()
        {
            InitializeComponent();
        }

        // If updating an existing map item, show the existing item info and disable changing info
        public void ShowForUpdate(string title, string description, string[] tags)
        {
            // Item title
            MapTitleEntry.Text = title;
            MapTitleEntry.IsEnabled = false;

            // Item description
            MapDescriptionEntry.Text = description;
            MapDescriptionEntry.IsEnabled = false;

            // Item tags
            MapTagsEntry.Text = string.Join(",", tags);
            MapTagsEntry.IsEnabled = false;

            // Show 'Update' rather than 'Save' for button text
            SaveMapButton.Text = "Update";
        }

        // A click handler for the save map button
        private void SaveButtonClicked(object sender, EventArgs e)
        {
            try
            {
                // Get information for the new portal item
                string title = MapTitleEntry.Text;
                string description = MapDescriptionEntry.Text;
                string[] tags = MapTagsEntry.Text.Split(',');

                // Make sure all required info was entered
                if (string.IsNullOrEmpty(title) || string.IsNullOrEmpty(description) || tags.Length == 0)
                {
                    throw new Exception("Please enter a title, description, and some tags to describe the map.");
                }

                // Create a new OnSaveMapEventArgs object to store the information entered by the user
                SaveMapEventArgs mapSavedArgs = new SaveMapEventArgs(title, description, tags);

                // Raise the OnSaveClicked event so the main activity can handle the event and save the map
                OnSaveClicked?.Invoke(this, mapSavedArgs);

                // Close the dialog
                Navigation.PopAsync();
            }
            catch (Exception ex)
            {
                // Show the exception message (dialog will stay open so user can try again)
                DisplayAlert("Error", ex.Message, "OK");
            }
        }

        private void CancelButtonClicked(object sender, EventArgs e)
        {
            // If the user cancels, just navigate back to the previous page
            Navigation.PopAsync();
        }
    }

    // Custom EventArgs class for containing portal item properties when saving a map
    public class SaveMapEventArgs : EventArgs
    {
        // Portal item title
        public string MapTitle { get; set; }

        // Portal item description
        public string MapDescription { get; set; }

        // Portal item tags
        public string[] Tags { get; set; }

        public SaveMapEventArgs(string title, string description, string[] tags) : base()
        {
            MapTitle = title;
            MapDescription = description;
            Tags = tags;
        }
    }
}

