            myMap.OperationalLayers.Add(operationalLayer);

            // Assign the map to the MapView.
            MyMapView.Map = myMap;

            // Populate the picker with spatial reference names.
            SpatialReferencePicker.ItemsSource = _spatialReferenceOptions.Select(sr => sr.Name).ToList();

            // Set the default selection to World Bonne.
            SpatialReferencePicker.SelectedIndex = _spatialReferenceOptions.FindIndex(sr => sr.Wkid == 54024);
