            _geomorphicCategoryField = await tenMeterBinField
                .ReplaceIf(isRaisedShoreline, 1)
                .ReplaceIf(isIceCovered, 2)
                .ReplaceIf(isIceFreeHighGround, 3)
                .EvaluateAsync();
