            // Apply the renderer to the graphics overlay (all graphics use the same symbol).
            myGraphicOverlay.Renderer = myRenderer;

            // Add the graphics overlay to the map view.
            MyMapView.GraphicsOverlays.Add(myGraphicOverlay);
