                    featureLayer.UnselectFeature(feature);
            }
            if (newValue is not null)
            {
                if (newValue.GeoElement is Feature feature && feature.FeatureTable?.Layer is FeatureLayer featureLayer)
                    featureLayer.SelectFeature(feature);
            }
        }
    }
